// Package runtime holds support code used by ALL code generated by
// nitro/json/gen (it is not generated itself — it is hand-written and
// imported by _gen.go files). This avoids duplicating parse logic in
// every package that uses the Phase 4 code generator.
package runtime

// Parser is a simple stateful parser that walks a JSON []byte by
// position, allocating only what is needed to extract values
// (strings must be copied; numbers/bools do not allocate).
type Parser struct {
	Data []byte
	Pos  int
}

// NewParser creates a Parser over the given []byte.
func NewParser(data []byte) *Parser {
	return &Parser{Data: data}
}

func (p *Parser) skipSpaces() {
	for p.Pos < len(p.Data) {
		switch p.Data[p.Pos] {
		case ' ', '\t', '\n', '\r':
			p.Pos++
		default:
			return
		}
	}
}

// ExpectByte consumes byte c at the current position (after spaces), or
// returns false if it is not found.
func (p *Parser) ExpectByte(c byte) bool {
	p.skipSpaces()
	if p.Pos >= len(p.Data) || p.Data[p.Pos] != c {
		return false
	}
	p.Pos++
	return true
}

// PeekByte reports (without consuming) whether the next non-space byte is c.
func (p *Parser) PeekByte(c byte) bool {
	p.skipSpaces()
	return p.Pos < len(p.Data) && p.Data[p.Pos] == c
}

// PeekNull reports whether the current value is the null literal.
func (p *Parser) PeekNull() bool {
	p.skipSpaces()
	return p.Pos+4 <= len(p.Data) && string(p.Data[p.Pos:p.Pos+4]) == "null"
}

// ParseKey reads "key": and returns the key (without quotes), leaving
// Pos just after the ':'.
func (p *Parser) ParseKey() (string, bool) {
	s, ok := p.ParseString()
	if !ok {
		return "", false
	}
	if !p.ExpectByte(':') {
		return "", false
	}
	return s, true
}

// ParseString reads a JSON string (assuming Pos points at the opening
// quote), handling basic escapes (\", \\, \/, \n, \t, \r). Copies
// bytes into a new string (safe for buffer reuse) — Phase 4 decision:
// prefer "safe" over "unsafe" by default, because the HTTP request
// buffer is recycled via a pool and strings via unsafe.Pointer could
// be silently corrupted after the request ends.
func (p *Parser) ParseString() (string, bool) {
	if !p.ExpectByte('"') {
		return "", false
	}
	start := p.Pos
	hasEscape := false
	for p.Pos < len(p.Data) && p.Data[p.Pos] != '"' {
		if p.Data[p.Pos] == '\\' {
			hasEscape = true
			p.Pos++
		}
		p.Pos++
	}
	if p.Pos >= len(p.Data) {
		return "", false
	}
	raw := p.Data[start:p.Pos]
	p.Pos++

	if !hasEscape {
		return string(raw), true
	}
	return unescapeJSONString(raw), true
}

func unescapeJSONString(raw []byte) string {
	out := make([]byte, 0, len(raw))
	for i := 0; i < len(raw); i++ {
		if raw[i] == '\\' && i+1 < len(raw) {
			i++
			switch raw[i] {
			case '"':
				out = append(out, '"')
			case '\\':
				out = append(out, '\\')
			case '/':
				out = append(out, '/')
			case 'n':
				out = append(out, '\n')
			case 't':
				out = append(out, '\t')
			case 'r':
				out = append(out, '\r')
			default:
				out = append(out, raw[i])
			}
			continue
		}
		out = append(out, raw[i])
	}
	return string(out)
}

// ParseInt reads a JSON number and returns it as int64. Scientific
// notation (1e10) is not supported — a known, documented limitation;
// typical API request/response numbers do not use that form.
func (p *Parser) ParseInt() (int64, bool) {
	p.skipSpaces()
	start := p.Pos
	if p.Pos < len(p.Data) && p.Data[p.Pos] == '-' {
		p.Pos++
	}
	digitsStart := p.Pos
	for p.Pos < len(p.Data) && p.Data[p.Pos] >= '0' && p.Data[p.Pos] <= '9' {
		p.Pos++
	}
	if p.Pos == digitsStart {
		return 0, false
	}
	neg := p.Data[start] == '-'
	var n int64
	for i := digitsStart; i < p.Pos; i++ {
		n = n*10 + int64(p.Data[i]-'0')
	}
	if neg {
		n = -n
	}
	return n, true
}

// ParseFloat reads a JSON number (including a fractional part) as float64.
// Same scientific-notation limitation as ParseInt.
func (p *Parser) ParseFloat() (float64, bool) {
	p.skipSpaces()
	start := p.Pos
	if p.Pos < len(p.Data) && p.Data[p.Pos] == '-' {
		p.Pos++
	}
	for p.Pos < len(p.Data) && p.Data[p.Pos] >= '0' && p.Data[p.Pos] <= '9' {
		p.Pos++
	}
	if p.Pos < len(p.Data) && p.Data[p.Pos] == '.' {
		p.Pos++
		for p.Pos < len(p.Data) && p.Data[p.Pos] >= '0' && p.Data[p.Pos] <= '9' {
			p.Pos++
		}
	}
	if p.Pos == start {
		return 0, false
	}
	return parseFloatManual(p.Data[start:p.Pos]), true
}

func parseFloatManual(b []byte) float64 {
	neg := false
	i := 0
	if len(b) > 0 && b[0] == '-' {
		neg = true
		i = 1
	}
	var intPart float64
	for ; i < len(b) && b[i] != '.'; i++ {
		intPart = intPart*10 + float64(b[i]-'0')
	}
	var fracPart float64
	var fracDiv float64 = 1
	if i < len(b) && b[i] == '.' {
		i++
		for ; i < len(b); i++ {
			fracPart = fracPart*10 + float64(b[i]-'0')
			fracDiv *= 10
		}
	}
	result := intPart + fracPart/fracDiv
	if neg {
		result = -result
	}
	return result
}

// ParseBool reads a true/false literal.
func (p *Parser) ParseBool() (bool, bool) {
	p.skipSpaces()
	if p.Pos+4 <= len(p.Data) && string(p.Data[p.Pos:p.Pos+4]) == "true" {
		p.Pos += 4
		return true, true
	}
	if p.Pos+5 <= len(p.Data) && string(p.Data[p.Pos:p.Pos+5]) == "false" {
		p.Pos += 5
		return false, true
	}
	return false, false
}

// SkipValue advances Pos past an arbitrary JSON value (string, number,
// bool, null, object, or array) without interpreting it. Used both to
// skip unknown fields and to delimit the byte range of a nested
// object/array before calling ParseJSON on it.
func (p *Parser) SkipValue() bool {
	p.skipSpaces()
	if p.Pos >= len(p.Data) {
		return false
	}
	switch p.Data[p.Pos] {
	case '"':
		_, ok := p.ParseString()
		return ok
	case '{':
		return p.skipBlock('{', '}')
	case '[':
		return p.skipBlock('[', ']')
	case 't':
		if p.Pos+4 <= len(p.Data) && string(p.Data[p.Pos:p.Pos+4]) == "true" {
			p.Pos += 4
			return true
		}
		return false
	case 'f':
		if p.Pos+5 <= len(p.Data) && string(p.Data[p.Pos:p.Pos+5]) == "false" {
			p.Pos += 5
			return true
		}
		return false
	case 'n':
		if p.Pos+4 <= len(p.Data) && string(p.Data[p.Pos:p.Pos+4]) == "null" {
			p.Pos += 4
			return true
		}
		return false
	default:
		start := p.Pos
		if p.Data[p.Pos] == '-' {
			p.Pos++
		}
		for p.Pos < len(p.Data) {
			c := p.Data[p.Pos]
			if (c >= '0' && c <= '9') || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
				p.Pos++
				continue
			}
			break
		}
		return p.Pos > start
	}
}

func (p *Parser) skipBlock(open, close byte) bool {
	if !p.ExpectByte(open) {
		return false
	}
	depth := 1
	for p.Pos < len(p.Data) && depth > 0 {
		c := p.Data[p.Pos]
		switch c {
		case '"':
			if _, ok := p.ParseString(); !ok {
				return false
			}
			continue
		case open:
			depth++
		case close:
			depth--
		}
		p.Pos++
	}
	return depth == 0
}

// AppendJSONEscapedString writes s into buf escaping the characters
// JSON requires: ", \, and control characters (< 0x20). Used by
// generated Marshal code for every string field.
func AppendJSONEscapedString(buf []byte, s string) []byte {
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"' || c == '\\':
			buf = append(buf, '\\', c)
		case c == '\n':
			buf = append(buf, '\\', 'n')
		case c == '\t':
			buf = append(buf, '\\', 't')
		case c == '\r':
			buf = append(buf, '\\', 'r')
		case c < 0x20:
			buf = append(buf, '\\', 'u', '0', '0',
				hexDigit(c>>4), hexDigit(c&0xF))
		default:
			buf = append(buf, c)
		}
	}
	return buf
}

func hexDigit(n byte) byte {
	if n < 10 {
		return '0' + n
	}
	return 'a' + (n - 10)
}
